const tokens = question.match(/\d+|[\+\-\*\/]/g);
if (!tokens) return 0;
let result = parseInt(tokens[0], 10);
for (let i = 1; i < tokens.length; i += 2) {
    const operator = tokens[i];
    const num = parseInt(tokens[i + 1], 10);
    switch (operator) {
      case "+":
        result += num;
        break;
      case "-":
        result -= num;
        break;
      case "*":
        result *= num;
        break;
      case "/":
        if (num === 0) throw new Error("Division by zero");
        result = Math.floor(result / num);
        break;
      default:
        throw new Error(`Unsupported operation: ${operator}`);
    }
  }
return result;

